class BankAccount {

    private int balance;

    public BankAccount(int startingBalance) {
        this.balance = startingBalance;
    }

    public boolean deposit(int cents) {
        if (cents <= 0) {
            return false;
        }
        this.balance += cents;
        return true;
    }

    public boolean withdraw(int cents) {
        if (cents <= 0 || cents > this.balance) {
            return false;
        }
        this.balance -= cents;
        return true;
    }

    public int getBalance() {
        return this.balance;
    }
}

