    def __init__(self, starting):
        self.__balance = starting

    def deposit(self, cents):
        if cents <= 0:
            return False
        self.__balance += cents
        return True

    def withdraw(self, cents):
        if cents <= 0 or cents > self.__balance:
            return False
        self.__balance -= cents
        return True

    def balance(self):
        return self.__balance

